#[component]
pub fn Icon(#[prop(into)] name: String, #[prop(into, optional)] class: String) -> impl IntoView {
    let class = if class.is_empty() { "size-4 shrink-0".to_string() } else { format!("shrink-0 {class}") };
    view! {
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor"
            stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class=class aria-hidden="true"
            inner_html=paths(&name)></svg>
    }
}

/// nrzPass-Logo (Schild mit Schluesselloch), gleich wie das App-Symbol.
#[component]
pub fn Logo(#[prop(into, optional)] class: String) -> impl IntoView {
    let class = if class.is_empty() { "size-8".to_string() } else { class };
    view! {
        <svg viewBox="0 0 256 256" class=class aria-label="nrzPass">
            <rect width="256" height="256" rx="56" fill="#18181b"/>
            <path d="M128 40 196 66v50c0 47-28.6 81-68 96-39.4-15-68-49-68-96V66Z" fill="#52525b"/>
            <path d="M128 58 182 79v40c0 38.5-22.4 66.8-54 80-31.6-13.2-54-41.5-54-80V79Z" fill="#e4e4e7"/>
            <circle cx="128" cy="112" r="22" fill="#52525b"/>
            <rect x="118" y="126" width="20" height="46" rx="10" fill="#52525b"/>
        </svg>
    }
}
